# Словарь понятий для межигрового сравнения механик. Понятия жанровые (экшен/рогалик/метроидвания), без имён
# и терминов конкретной игры-референса: игра попадает под понятие через синонимы (RU/EN) или через коллекцию.
#
# Поля понятия: id (латиница, уникален) · ru / en (имя) · def (определение) · syn_ru / syn_en (синонимы) ·
#   parent (id родителя; поиск по родителю включает потомков) · collections (список коллекций таксономии: все
#   записи этих коллекций получают понятие неявно, source=coll).
# Синоним: слова сравниваются по основе (русский Snowball; английский — без хвостового -s). «слово*» — любое
#   продолжение (поджиг* = поджигает, поджигание). Несколько слов — фраза подряд. Регистр и ё не важны.
# Правило попадания (tag.py): совпадение в заголовке — 3 очка, в теле/summary/числах — 1 за каждое различное
#   совпадение; тег ставится при сумме >= 3 (заголовок либо >= 3 различных совпадений в теле).
version: 1
concepts:
# ---------- семейства таксономии (корни) ----------
- {id: f_feel_core, ru: Управление и отклик, en: Control and feel, def: "Ввод игрока, движение героя, тайминги атак, конвейер статов, автоматы состояний.", syn_ru: [], syn_en: []}
- {id: f_anim_physics, ru: Анимация, коллизии, физика, en: Animation collisions physics, def: "Клипы, графы переходов, события анимации, хитбоксы, физические тела.", syn_ru: [], syn_en: []}
- {id: f_combat, ru: Боевая система, en: Combat system, def: "Урон, способности, снаряды, статусы и правила расчёта урона.", syn_ru: [], syn_en: []}
- {id: f_entities, ru: Враги, боссы, союзники, en: Enemies bosses allies, def: "Ростер врагов, их поведение, паттерны боссов, призванные существа.", syn_ru: [], syn_en: []}
- {id: f_builds, ru: Билды и прогрессия, en: Builds and progression, def: "Предметы, эффекты, синергии, билды, облики, мета-открытия.", syn_ru: [], syn_en: []}
- {id: f_numbers, ru: Числа и экономика, en: Numbers and economy, def: "Кривые, валюты, цены, дроп, сложность и метрики забега.", syn_ru: [], syn_en: []}
- {id: f_world, ru: Мир и уровни, en: World and levels, def: "Комнаты, генерация этажей, встречи, ловушки, темы, структура забега.", syn_ru: [], syn_en: []}
- {id: f_presentation, ru: Подача и обратная связь, en: Presentation and feedback, def: "Эффекты, камера, свет, звук, интерфейс, арт-инвентарь, замеры отклика.", syn_ru: [], syn_en: []}
- {id: f_meta_tech, ru: Мета и техника, en: Meta and tech, def: "Диалоги, достижения, обучение, сохранения, мультиплеер, архитектура кода.", syn_ru: [], syn_en: []}
# ---------- понятия-коллекции (53; записи коллекции получают их неявно) ----------
- {id: loco_profile, ru: Профиль движения, en: Locomotion profile, def: "Скорость, разгон, рывок и прыжок героя или врага как набор параметров.", syn_ru: [профиль движения, параметры движения, локомоци*], syn_en: [locomotion, movement profile], parent: f_feel_core, collections: [locomotion_profiles]}
- {id: input_binding, ru: Привязки ввода, en: Input bindings, def: "Действия ввода, раскладки, режимы прицеливания, буфер ввода.", syn_ru: [привязк* ввода, раскладк*, управление с клавиатуры], syn_en: [input binding*, keybind*, control scheme], parent: f_feel_core, collections: [input_bindings]}
- {id: attack_timeline, ru: Тайминги атаки, en: Attack timeline, def: "Покадровые фазы атаки: замах, активные кадры, восстановление.", syn_ru: [тайминги атак*, покадров* атак*, фазы атаки], syn_en: [frame data, attack timeline, attack timing], parent: f_feel_core, collections: [attack_timelines]}
- {id: stat_pipeline, ru: Конвейер статов, en: Stat pipeline, def: "Порядок применения модификаторов к характеристике.", syn_ru: [конвейер стат*, реестр характеристик, порядок модификаторов], syn_en: [stat pipeline, stat modifier order, stat registry], parent: f_feel_core, collections: [stat_pipelines]}
- {id: state_machine, ru: Автомат состояний, en: State machine, def: "Конечный автомат состояний сущности и условия переходов.", syn_ru: [автомат* состояний, конечный автомат, машина состояний], syn_en: [state machine, fsm, finite state machine], parent: f_feel_core, collections: [fsm_catalogs]}
- {id: anim_clip, ru: Анимационный клип, en: Animation clip, def: "Клип анимации: длина, частота кадров, зацикленность.", syn_ru: [анимационн* клип*, клип анимации, длина клипа], syn_en: [animation clip*, clip length], parent: f_anim_physics, collections: [anim_clips]}
- {id: anim_graph, ru: Граф анимаций, en: Animation graph, def: "Переходы между клипами аниматора, блендинг.", syn_ru: [граф анимаци*, переход* аниматора, блендинг], syn_en: [animator graph, animation graph, anim transition*, blend time], parent: f_anim_physics, collections: [anim_state_graphs]}
- {id: anim_event, ru: События анимации, en: Animation events, def: "События на таймлайне клипа: звук, эффект, хитбокс, камера.", syn_ru: [событи* анимации, событи* клипа, анимационн* событи*], syn_en: [animation event*, anim event*, clip event*], parent: f_anim_physics, collections: [anim_event_timelines]}
- {id: hitbox, ru: Хитбокс, en: Hitbox, def: "Объём, наносящий или принимающий попадание; коллайдеры и триггеры.", syn_ru: [хитбокс*, хёртбокс*, хертбокс*, коллайдер*, зона поражения], syn_en: [hitbox*, hurtbox*, collider*, hit box*], parent: f_anim_physics, collections: [collision_geometry]}
- {id: physics_body, ru: Физическое тело, en: Physics body, def: "Тела, слои, материалы, масса, сопротивление движению.", syn_ru: [физическ* тел*, слои коллизий, слой коллизий, масса тела], syn_en: [physics body, rigidbody, collision layer*, physics layer*], parent: f_anim_physics, collections: [physics_setup]}
- {id: skill_numbers, ru: Числа умения, en: Skill numbers, def: "Числовая запись умения: урон, отбрасывание, множители.", syn_ru: [числа умени*, параметры умени*, запись умения], syn_en: [skill numbers, skill record*, skill data], parent: f_combat, collections: [skill_records]}
- {id: ability, ru: Способность героя, en: Hero ability, def: "Активная способность или заклинание героя: стихия, перезарядка, тип применения.", syn_ru: [способност*, заклинани*, умени*], syn_en: [ability, abilities, spell*, skill*], parent: f_combat, collections: [arcana_catalog]}
- {id: projectile, ru: Снаряд, en: Projectile, def: "Снаряды и объекты-атаки: скорость, дальность, пробивание.", syn_ru: [снаряд*, пул*, стрел* , выстрел*], syn_en: [projectile*, bullet*, missile*], parent: f_combat, collections: [projectile_families]}
- {id: status_effect, ru: Статус-эффект, en: Status effect, def: "Состояние на сущности: длительность, тики, наложение, иммунитет.", syn_ru: [статус*, состояни* на сущност*, эффект* состояни*], syn_en: [status effect*, status ailment*, debuff*, buff*], parent: f_combat, collections: [status_effects]}
- {id: damage_calc, ru: Расчёт урона, en: Damage calculation, def: "Порядок этапов расчёта итогового урона и защиты.", syn_ru: [расчёт урона, расчет урона, формула урона, итогов* урон], syn_en: [damage calculation, damage formula, damage pipeline, final damage], parent: f_combat, collections: [damage_rules]}
- {id: enemy_unit, ru: Враг, en: Enemy, def: "Запись ростера врагов: здоровье, скорость, дальность, роль.", syn_ru: [враг*, противник*, мобы, моб], syn_en: [enemy, enemies, mob, mobs, hostile], parent: f_entities, collections: [enemy_roster]}
- {id: enemy_ai, ru: ИИ врага, en: Enemy AI, def: "Поведение врага: агро, радиусы атаки, тревога, дистанция боя.", syn_ru: [ии враг*, поведение враг*, искусственн* интеллект], syn_en: [enemy ai, enemy behavior, enemy behaviour], parent: f_entities, collections: [enemy_ai_behaviors]}
- {id: boss_pattern, ru: Паттерн босса, en: Boss pattern, def: "Атаки, фазы и окна уязвимости босса.", syn_ru: [босс*, паттерн* босса, атаки босса], syn_en: [boss, bosses, boss pattern*, boss fight], parent: f_entities, collections: [boss_patterns]}
- {id: summon_ally, ru: Призванный союзник, en: Summoned ally, def: "Призванные существа, спутники и питомцы героя.", syn_ru: [призванн* существ*, союзник*, спутник*, питомц*, миньон*], syn_en: [summoned creature*, ally, allies, companion*, minion*, pet, pets], parent: f_entities, collections: [summons_allies]}
