- {id: loco_profile, ru: Профиль движения, en: Locomotion profile, def: "Скорость, разгон, рывок и прыжок героя или врага как набор параметров.", syn_ru: [профиль движения, параметры движения, локомоци*], syn_en: [locomotion, movement profile], parent: f_feel_core, collections: [locomotion_profiles]}
